}
function buildScene() {
  gScene.rect(FW, FH).fill('#ffffff');

  /* trunk */
  var trunk = gScene.path(
    'M862,150 C858,220 848,300 842,350 C838,382 828,392 812,400 L856,400 ' +
    'C868,398 872,384 874,366 C877,344 888,340 896,356 C903,370 906,392 918,400 ' +
    'L958,400 C944,392 938,366 936,330 C932,270 944,190 950,150 Z'
