  var pts = [], i;
  for (i = 0; i < 26; i++) {
    var a = i / 26 * 2 * Math.PI, f = canopyF(a);
    pts.push([TREE.cx + TREE.rx * f * Math.cos(a), TREE.cy + TREE.ry * f * Math.sin(a)]);
  }
  var canopy = gScene.path(closedSmoothPath(pts)).fill(GREEN).stroke({ color: '#000', width: 3 });

  hoverable(canopy, 'Tree canopy — a bright radiance source; rays leaving it carry green light.',
    'Radiance source', 'Every patch of the canopy emits (reflects) light in all directions. Those rays are part of the plenoptic function L(x, y, θ) at every point of space they pass through.');
  hoverable(trunk, 'Tree trunk — darker brown radiance.', null, null);

  /* bird */
  var bird = gScene.path(
    'M1129,72 C1131,56 1136,44 1145,36 C1138,31 1135,23 1137,15 C1142,22 1149,25 1157,24 ' +
    'C1164,23 1170,19 1173,13 C1174,22 1169,31 1161,35 C1168,39 1172,46 1172,54 ' +
    'C1166,46 1158,42 1149,43 C1142,44 1135,55 1133,72 Z'
  ).fill('none').stroke({ color: '#000', width: 2.2, linejoin: 'round' });
  hoverable(bird, 'A bird — also a source of rays filling the surrounding space.', null, null);

  /* ground */
  gScene.line(0, GROUND_Y, FW, GROUND_Y).stroke({ color: '#000', width: 6 });

  /* labels */
  halo(gLab.text('Pinhole camera').font({ family: 'sans-serif', size: 21, anchor: 'middle', fill: '#000' })
    .center(152, 142));
  halo(gLab.text('red dot = sampling location   ·   arrow = incoming ray   ·   dark green = light coming from the canopy')
    .font({ family: 'sans-serif', size: 9.5, anchor: 'start', fill: '#666' }).move(8, 380));
}

/* ---------------- camera ---------------- */
function drawCamera() {
  gCam.clear();
  var g = gapPx(), gt = PIN_Y - g / 2, gb = PIN_Y + g / 2;
  var st = { color: '#000', width: 3, linecap: 'square' };

  var inner = gCam.rect(CAM.r - CAM.l, CAM.b - CAM.t).move(CAM.l, CAM.t).fill('#ffffff').opacity(0.01);
  hoverable(inner, 'Inside the camera: walls block almost every direction.',
    'Pinhole camera', 'The box is opaque except for one tiny hole. A point on the image plane therefore receives light from essentially one direction only — the camera does not create the image, it masks the plenoptic function down to a sparse sample.');

  gCam.line(CAM.l, CAM.t, CAM.l, CAM.b).stroke(st);
  gCam.line(CAM.l, CAM.t, CAM.r, CAM.t).stroke(st);
  gCam.line(CAM.l, CAM.b, CAM.r, CAM.b).stroke(st);
  gCam.line(CAM.r, CAM.t, CAM.r, gt).stroke(st);
  gCam.line(CAM.r, gb, CAM.r, CAM.b).stroke(st);

  var ap = gCam.rect(16, Math.max(g, 10)).center(CAM.r, PIN_Y).fill('#ffffff').opacity(0.01);
  hoverable(ap, 'Pinhole aperture — width ' + state.aperture.toFixed(2),
    'The aperture', 'The aperture selects which directions survive. Narrow → one ray per image point (sharp). Wide → a cone of directions lands on the same point (blurred).');
}

/* ---------------- dynamic layer ---------------- */
function starburst(grpParent, p, selected) {
  var g = grpParent.group();
  for (var i = 0; i < 20; i++) {
    var a = i / 20 * 2 * Math.PI + 0.16;
    var h = traceScene(p.x, p.y, a);
    var Rout = Math.max(32, Math.min(106, h.dist - 4));
    var dx = Math.cos(a), dy = -Math.sin(a);
    var col = (h.type === 'tree') ? '#1c6b12' : ((h.type === 'trunk') ? '#4b3520' : '#000');
    arrow(g, p.x + dx * Rout, p.y + dy * Rout, p.x + dx * 14, p.y + dy * 14, col, 1.4, 9);
  }
  if (selected) g.circle(44).center(p.x, p.y).fill('none').stroke({ color: '#000', width: 1.4, dasharray: '4,3' });
  var d = g.circle(24).center(p.x, p.y).fill(RED);
  hoverable(d, 'Free-space sample point: radiance arrives from (almost) every direction.',
    'A point in free space', 'The plenoptic function L(x, y, θ) is defined here even though nothing physical sits at this spot. Light from the sky, the canopy and the ground all stream through, in all directions at once.');
