/* ---------------- canvas ---------------- */
var FW = 1200, FH = 415;
var fig = SVG().addTo(document.getElementById('container')).size('100%', '100%');
fig.viewbox(0, 0, FW, FH);

var gScene = fig.group(), gCam = fig.group(), gDyn = fig.group(),
    gPanel = fig.group(), gAnn = fig.group(), gLab = fig.group();

/* ---------------- geometry ---------------- */
var GROUND_Y = 404;
var CAM = { l: 73, r: 227, t: 163, b: 375 };
var PIN_Y = 270;
var DOT_U = { x: 88, y: 196 }, DOT_D = { x: 88, y: 300 };
var FREE_B = { x: 566, y: 109 };
var TREE = { cx: 892, cy: 132, rx: 196, ry: 102 };
var GREEN = '#2bc41f', BROWN = '#8f5f3b', RED = '#ff0000';

var RAD = {
  sky:     { L: 1.00, c: '#7fb2d9' },
  tree:    { L: 0.60, c: GREEN },
  trunk:   { L: 0.45, c: BROWN },
  ground:  { L: 0.25, c: '#555555' },
  camera:  { L: 0.08, c: '#333333' },
  blocked: { L: 0.00, c: '#cccccc' }
};

var state = { mode: 'free', aperture: 0.08, sample: { x: 460, y: 293 },
              camDot: 'upper', crossing: false, step: 0 };

/* ---------------- helpers ---------------- */
function canopyF(a) {
  return 1 + 0.055 * Math.sin(3 * a + 0.7) + 0.035 * Math.cos(5 * a + 1.9) + 0.028 * Math.sin(7 * a + 0.3);
}
function inCanopy(x, y) {
  var dx = x - TREE.cx, dy = y - TREE.cy, f = canopyF(Math.atan2(dy, dx));
  var u = dx / (TREE.rx * f), v = dy / (TREE.ry * f);
  return (u * u + v * v) <= 1;
}
function inTrunk(x, y) { return x > 838 && x < 956 && y > 130 && y < GROUND_Y; }
function inCamBox(x, y) { return x >= CAM.l - 2 && x <= CAM.r + 2 && y >= CAM.t - 2 && y <= CAM.b + 2; }

function mk(type, dist) { return { type: type, dist: dist, L: RAD[type].L, c: RAD[type].c }; }

function traceScene(px, py, a) {
  var dx = Math.cos(a), dy = -Math.sin(a);
  for (var t = 2; t < 1700; t += 4) {
    var x = px + dx * t, y = py + dy * t;
    if (y >= GROUND_Y) return mk('ground', t);
    if (x < -30 || x > FW + 30 || y < -30) return mk('sky', t);
    if (inCanopy(x, y)) return mk('tree', t);
    if (inTrunk(x, y)) return mk('trunk', t);
    if (inCamBox(x, y)) return mk('camera', t);
  }
  return mk('sky', 1700);
}
function gapPx() { return 4 + state.aperture * 56; }
function traceCam(dot, a) {
  var dx = Math.cos(a), dy = -Math.sin(a);
  if (dx <= 1e-6) return mk('blocked', 10);
  var t = (CAM.r - dot.x) / dx, yAt = dot.y + dy * t, g = gapPx();
  if (yAt < PIN_Y - g / 2 || yAt > PIN_Y + g / 2) return mk('blocked', t);
  return traceScene(CAM.r + 3, yAt, a);
}
function camDotObj() { return state.camDot === 'upper' ? DOT_U : DOT_D; }
function sampleRadiance(a) {
  return (state.mode === 'camera') ? traceCam(camDotObj(), a)
                                   : traceScene(state.sample.x, state.sample.y, a);
}

function arrow(g, x1, y1, x2, y2, color, w, head) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1;
  var ux = dx / L, uy = dy / L;
  head = head || 9;
  var bx = x2 - ux * head, by = y2 - uy * head;
  g.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'butt' });
