  pairs.forEach(function (p) {
    for (var i = 0; i < n; i++) {
      var frac = (n === 1) ? 0.5 : i / (n - 1);
      var gy = gt + frac * gp;
      var vx = CAM.r - p.dot.x, vy = gy - p.dot.y, L = Math.hypot(vx, vy);
      var ux = vx / L, uy = vy / L, len = 205;
      arrow(g, p.dot.x + ux * len, p.dot.y + uy * len, p.dot.x + ux * 11, p.dot.y + uy * 11,
            p.col, state.crossing ? 2.2 : 1.7, 11);
    }
  });
}

function distToWall(dot, dx, dy) {
  var ts = [];
  if (dx > 1e-6) ts.push((CAM.r - dot.x) / dx);
  if (dx < -1e-6) ts.push((CAM.l - dot.x) / dx);
  if (dy > 1e-6) ts.push((CAM.b - dot.y) / dy);
  if (dy < -1e-6) ts.push((CAM.t - dot.y) / dy);
  ts = ts.filter(function (t) { return t > 0; });
  return ts.length ? Math.min.apply(null, ts) : 0;
}
function drawStubs(g, dot) {
  for (var k = 0; k < 30; k++) {
    var a = k / 30 * 2 * Math.PI;
    var h = traceCam(dot, a);
    if (h.L > 0.02) continue;
    var dx = Math.cos(a), dy = -Math.sin(a);
    var r0 = 14, r1 = Math.min(27, distToWall(dot, dx, dy) - 1);
    if (r1 < r0 + 3) continue;
    g.line(dot.x + dx * r0, dot.y + dy * r0, dot.x + dx * r1, dot.y + dy * r1)
      .stroke({ color: '#c9c9c9', width: 1.3 });
  }
}

function drawDynamic() {
  gDyn.clear();
  var camMode = (state.mode === 'camera');

  var gFree = gDyn.group().opacity(camMode ? 0.22 : 1);
  starburst(gFree, FREE_B, false);
  starburst(gFree, state.sample, !camMode);

  if (camMode) {
    var blurR = 6 + Math.max(0, gapPx() - 8) * 0.55;
    [DOT_U, DOT_D].forEach(function (d) {
      gDyn.circle(blurR * 2).center(d.x, d.y).fill(RED).opacity(0.22);
      drawStubs(gDyn, d);
    });
  }
  drawCamRays(gDyn);

  [{ d: DOT_U, key: 'upper' }, { d: DOT_D, key: 'lower' }].forEach(function (o) {
    if (camMode && state.camDot === o.key) {
      gDyn.circle(46).center(o.d.x, o.d.y).fill('none')
        .stroke({ color: '#000', width: 1.4, dasharray: '4,3' });
    }
    var c = gDyn.circle(24).center(o.d.x, o.d.y).fill(RED);
    if (state.crossing) {
      c.stroke({ color: o.key === 'upper' ? '#0b57d0' : '#e08200', width: 3 });
    }
    hoverable(c, 'Image-plane point (' + o.key + '): only directions through the pinhole carry light.',
      'A point on the image plane', 'This is a "pixel". Almost every direction is dark because the walls block it; only the narrow cone through the aperture carries radiance. The camera image is a sparse slice of the plenoptic function.');
  });
}

/* ---------------- polar panel ---------------- */
function drawPanel() {
  gPanel.clear();
  gPanel.rect(166, 198).move(230, 4).radius(7).fill('#ffffff').opacity(0.93)
    .stroke({ color: '#e4e4e4', width: 1 });

  var cx = 313, cy = 100, baseR = 10, R = 54, N = 132, on = 0;
  gPanel.circle((baseR + R) * 2).center(cx, cy).fill('none')
    .stroke({ color: '#cccccc', width: 1, dasharray: '3,3' });

  for (var k = 0; k < N; k++) {
    var a = k / N * 2 * Math.PI;
    var h = sampleRadiance(a);
    var dx = Math.cos(a), dy = -Math.sin(a);
    if (h.L > 0.02) {
      on++;
      gPanel.line(cx + dx * baseR, cy + dy * baseR, cx + dx * (baseR + h.L * R), cy + dy * (baseR + h.L * R))
        .stroke({ color: h.c, width: 2.4 });
    } else {
      gPanel.line(cx + dx * baseR, cy + dy * baseR, cx + dx * (baseR + 3.5), cy + dy * (baseR + 3.5))
        .stroke({ color: '#e0e0e0', width: 2.2 });
    }
  }
  gPanel.circle(8).center(cx, cy).fill(RED);

  gPanel.text('L(θ)  radiance vs. direction')
    .font({ family: 'sans-serif', size: 10.5, anchor: 'middle', fill: '#333' }).center(cx, 18);

  var p = (state.mode === 'camera') ? camDotObj() : state.sample;
  var sx = (p.x / FW * 10).toFixed(1), sy = ((GROUND_Y - p.y) / FW * 10).toFixed(1);
  var where = (state.mode === 'camera') ? ('image plane · ' + state.camDot + ' point') : 'free space';
  gPanel.text('(x, y) = (' + sx + ', ' + sy + ')  ·  ' + where)
    .font({ family: 'sans-serif', size: 9.5, anchor: 'start', fill: '#555' }).move(238, 168);
  var pct = Math.round(on / N * 100);
  gPanel.text('directions carrying light: ' + pct + '%')
    .font({ family: 'sans-serif', size: 9.5, anchor: 'start', fill: pct > 50 ? '#1c6b12' : '#b00000' })
    .move(238, 181);

  var hit = gPanel.rect(166, 198).move(230, 4).fill('#fff').opacity(0.001);
  hoverable(hit, 'Distance from the centre = radiance arriving from that direction.',
    'The angular distribution', 'This rose plot is L(θ) at the selected point. In free space it is full and bumpy (light from everywhere); on the image plane it collapses to a single narrow spike through the pinhole. A NeRF learns exactly this function over all of space.');
}

/* ---------------- step-5 annotation ---------------- */
function drawAnn() {
  gAnn.clear();
  if (!state.crossing) return;
  var rows = [
    { c: '#0b57d0', t: 'upper dot  ←  ray from below' },
    { c: '#e08200', t: 'lower dot  ←  ray from above' }
  ];
  rows.forEach(function (r, i) {
    var y = 212 + i * 14;
    gAnn.line(238, y, 258, y).stroke({ color: r.c, width: 2.6 });
    halo(gAnn.text(r.t).font({ family: 'sans-serif', size: 9, anchor: 'start', fill: '#333' }).move(263, y - 6));
  });
}

/* ---------------- redraw ---------------- */
function redrawAll() { drawCamera(); drawDynamic(); drawPanel(); drawAnn(); }

/* ---------------- interactions ---------------- */
function toggle_locationMode(on) { state.mode = on ? 'camera' : 'free'; redrawAll(); }
function update_apertureSize(v) { state.aperture = v; redrawAll(); }
function trigger_swapDot() {
  state.camDot = (state.camDot === 'upper') ? 'lower' : 'upper';
  if (state.mode !== 'camera') {
    state.mode = 'camera';
    document.getElementById('locationModeInput').checked = true;
  }
  redrawAll();
}

function toVB(e) {
  var pt = fig.node.createSVGPoint();
  pt.x = e.clientX; pt.y = e.clientY;
  var m = fig.node.getScreenCTM();
  if (!m) return { x: 0, y: 0 };
  var p = pt.matrixTransform(m.inverse());
  return { x: p.x, y: p.y };
}
fig.on('click', function (e) {
  var p = toVB(e);
  if (state.mode === 'camera') {
    state.camDot = (Math.abs(p.y - DOT_U.y) < Math.abs(p.y - DOT_D.y)) ? 'upper' : 'lower';
    redrawAll();
    return;
  }
  if (p.x < 25 || p.x > FW - 25 || p.y < 25 || p.y > GROUND_Y - 20) return;
  if (inCanopy(p.x, p.y) || inTrunk(p.x, p.y) || inCamBox(p.x, p.y)) return;
  state.sample = { x: p.x, y: p.y };
  redrawAll();
});

/* ---------------- demo steps ---------------- */
var STEPS = [
  { t: 'Light everywhere, in every direction',
    n: 'A red dot marks a sample point floating in open air between the camera and the tree. Arrows stream into it from every direction — green-tinted from the canopy, bright from the sky — because radiance arrives there from the whole surrounding scene.',
    s: { mode: 'free', ap: 0.08, sample: { x: 460, y: 293 }, camDot: 'upper', crossing: false } },
  { t: 'Move the point: the field is continuous',
    n: 'Click anywhere in the sky or near the tree to relocate the sample point. The polar plot of L(θ) changes smoothly as you move, showing the plenoptic function is defined at every location, not just at cameras or surfaces.',
    s: { mode: 'free', ap: 0.08, sample: { x: 676, y: 200 }, camDot: 'upper', crossing: false } },
  { t: 'Step inside the pinhole camera',
    n: 'Now the sample point sits on the camera\'s image plane. Nearly all directions are dead (grey stubs) — the camera walls block them — and a single arrow squeezes through the pinhole. The dense star has collapsed to one spike.',
    s: { mode: 'camera', ap: 0.08, sample: { x: 460, y: 293 }, camDot: 'upper', crossing: false } },
  { t: 'Open the aperture and blur the image',
    n: 'Widening the pinhole admits a cone of directions at each image point, so several rays now overlap on one spot and the picture blurs. A camera image is just a 2D slice of the plenoptic function, selected by the aperture.',
    s: { mode: 'camera', ap: 0.60, sample: { x: 460, y: 293 }, camDot: 'upper', crossing: false } },
  { t: 'Two points, an upside-down image',
    n: 'Compare the upper and lower image-plane points: the one high on the wall receives light from low in the scene and vice versa. The crossing rays through the pinhole are why the recorded image is inverted.',
    s: { mode: 'camera', ap: 0.08, sample: { x: 460, y: 293 }, camDot: 'upper', crossing: true } }
];

function applyStep(i) {
  i = Math.max(0, Math.min(STEPS.length - 1, i));
  state.step = i;
  var s = STEPS[i].s;
  state.mode = s.mode;
  state.aperture = s.ap;
  state.sample = { x: s.sample.x, y: s.sample.y };
  state.camDot = s.camDot;
  state.crossing = s.crossing;

  document.getElementById('locationModeInput').checked = (s.mode === 'camera');
  document.getElementById('apertureSizeInput').value = s.ap;
  document.getElementById('apertureSizeVal').value = s.ap.toFixed(2);
  document.getElementById('stepTitle').textContent = STEPS[i].t;
  document.getElementById('demoNarration').textContent = STEPS[i].n;
  document.getElementById('stepLabel').textContent = (i + 1) + ' / ' + STEPS.length;
  redrawAll();
}
function nextStep() { applyStep(state.step + 1); }
function prevStep() { applyStep(state.step - 1); }

/* ---------------- boot ---------------- */
buildScene();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

